    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        char[] chars = new char[n];
        long[] values = new long[n];
        for (int i = 0; i < n; i++) {
            chars[i] = st.nextToken().charAt(0);
            values[i] = Long.parseLong(st.nextToken());
        }
        Map<Character, List<Long>> groups = groupByCharacter(chars, values);
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Character, List<Long>> e : new TreeMap<>(groups).entrySet()) {
            sb.append(e.getKey());
            for (long v : e.getValue()) sb.append(' ').append(v);
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

