def gen(rng):
    def fmt(ps):
        return str(len(ps)) + '\n' + '\n'.join(f'{c} {v}' for c, v in ps)

    letters = 'abcdefghijklmnopqrstuvwxyz'
    tests = [
        fmt([('a', 1)]),
        fmt([('z', -5)]),
        fmt([('q', 0), ('q', 0), ('q', 0)]),
        fmt([('b', 2), ('a', 1)]),
        fmt([('c', 10**9), ('a', -10**9), ('c', -10**9), ('a', 10**9)]),
    ]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for k in (1, 3, 26):
            tests.append(fmt([(rng.choice(letters[:k]), rng.randint(-20, 20)) for _ in range(n)]))
    tests.append(fmt([(rng.choice(letters), rng.randint(-10**9, 10**9)) for _ in range(100000)]))
    tests.append(fmt([('m', rng.randint(-10**9, 10**9)) for _ in range(100000)]))
    tests.append(fmt([(letters[i % 26], i) for i in range(100000)]))
    return tests
